using System;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class WindAuditTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why,double tol=1e-9){Check(Math.Abs(a-b)<tol,why+" (got "+a+", expected "+b+")");}
 // Flat terrain of one land cover; each ray samples every 100 m to 3.2 km.
 static WindTerrain Flat(int cover,Func<int,double,double> elevation=null){var t=new WindTerrain{Lat=14.6,Lon=121,Radius=3200,Acquired=DateTime.UtcNow};for(int r=0;r<24;r++)for(double d=0;d<=3200;d+=100)t.Rays[r].Add(new WindSample{D=d,Z=elevation==null?10:elevation(r,d),Cover=cover});for(int c=0;c<8;c++)for(double d=-1000;d<=1000;d+=100)t.Cross[c].Add(new WindSample{D=d,Z=10,Cover=cover});return t;}
 static void Main(){
  // Exposure B: trees everywhere; h = 6 m needs 457.2 m of B.
  var b=Flat(10);var dirs=WindAssessment.Calculate(b,6,250,.85,6);Check(dirs.All(d=>d.Exposure=="B"),"all B");var audit=dirs[0].ExposureAudit;Check(audit.Rays==5,"five distinct rays across both 45° sectors");Near(audit.BFetch,457.2,"B fetch for h ≤ 9.1 m");Near(audit.DFetch,1524,"D fetch");Near(audit.Transition,182.88,"D transition");Check(audit.Reason.StartsWith("Exposure B"),"B reason explained");Check(audit.Checks.Any(c=>c[1].Contains("±45")||c[1].Contains("−45° to +45°")),"sector investigation recorded");
  Near(WindAssessment.BFetch(12),792.48,"B fetch for h > 9.1 m");Near(WindAssessment.BFetch(50),1000,"B fetch 20h");
  // Water on the +30° ray of wind-from N (ray index 3 = NE*3) from 100 m to 3.2 km: outside the old ±15° rays, inside ±45°.
  var water=Flat(10);for(int i=0;i<water.Rays[4].Count;i++)if(water.Rays[4][i].D>=100)water.Rays[4][i].Cover=80;dirs=WindAssessment.Calculate(water,6,250,.85,6);Check(dirs[0].Exposure=="D","water within ±45° makes wind-from N Exposure D");Check(dirs[0].ExposureAudit.SmoothRays==1&&dirs[0].ExposureAudit.Reason.Contains("more severe"),"partial D explained");Check(WindAssessment.Exposure(water.Rays.Take(3),6)=="B","old narrow sector would have missed it");Check(dirs[4].Exposure=="B","opposite direction unaffected");
  // Water starting beyond the transition distance does not give D.
  var far=Flat(30);for(int r=0;r<24;r++)foreach(var s in far.Rays[r])if(s.D>=400)s.Cover=80;dirs=WindAssessment.Calculate(far,6,250,.85,6);Check(dirs.All(x=>x.Exposure=="C"),"water starting 400 m away (> 182.88 m) with grass upwind is C");Check(dirs[0].ExposureAudit.Reason.Contains("too far"),"C reason mentions water too far");
  // Exposure C: B only for 300 m.
  var mixed=Flat(10);foreach(var s in mixed.Rays[1])if(s.D>300)s.Cover=30;dirs=WindAssessment.Calculate(mixed,6,250,.85,6);Check(dirs[0].Exposure=="C"&&dirs[0].ExposureAudit.Reason.Contains("300"),"B interrupted at 300 m on one ray gives C with the distance");
  // Unknown land cover is unresolved, never C.
  var u=Flat(10);u.Rays[2][5].Cover=0;dirs=WindAssessment.Calculate(u,6,250,.85,6);Check(dirs[0].Exposure=="Unresolved"&&!WindTin.Finite(dirs[0].Kzt),"no-data stays unresolved");Check(dirs[0].TopographicReason.Contains("UNRESOLVED"),"Kzt unresolved reason");
  // Low relief: Kzt = 1 with the height condition shown as NOT MET.
  dirs=WindAssessment.Calculate(Flat(30),10,250,.85);Check(dirs.All(x=>x.Kzt==1&&x.Shape=="Low relief"),"flat terrain Kzt 1");Check(dirs[0].TopographicChecks.Any(r=>r[0].StartsWith("Condition 5")&&r[1]=="NOT MET"),"condition 5 explained");Check(dirs[0].TopographicChecks.Any(r=>r[1].Contains("(1 + 0)² = 1.00")),"unity substitution shown");
  // Hill: site on top of a 60 m hill (Exposure C), wind from N uses up ray index 1 and down ray index 13.
  Func<int,double,double> hill=(r,dist)=>r==1||r==13?Math.Max(0,60-dist*60/600.0):0;var h=Flat(30,hill);dirs=WindAssessment.Calculate(h,10,250,.85);var n=dirs[0];
  Check(n.Exposure=="C","grass gives C");Near(n.H,60,"hill height from upwind base");Near(n.Lh,300,"Lh to half height",1e-6);Check(n.Shape=="Hill"||n.Shape=="Ridge","feature identified: "+n.Shape);Check(n.TopographicChecks.Any(r=>r[0].StartsWith("Condition 4")&&r[1]=="MET"),"slope condition met");Check(n.TopographicChecks.Any(r=>r[0].StartsWith("Condition 3")&&r[1]=="MET"),"upper half met");Check(n.TopographicChecks.Any(r=>r[0].StartsWith("Condition 1")&&r[1]=="REVIEW"),"isolation listed for review");Check(n.TopographicChecks.Any(r=>r[0].StartsWith("Condition 2")&&r[1]=="MET"),"a hill on flat ground is twice the upwind terrain");
  var k=WindAssessment.Factors(60,300,0,10,"C",n.Shape);Near(n.Kzt,k[3],"Kzt equals factor formula");Check(n.Kzt>1.3,"speed-up applied at crest: "+n.Kzt);Check(n.TopographicChecks.Any(r=>r[0]=="Substitution"&&r[1].Contains("Kzt = (1 + ")),"Kzt substitution shown");Near(n.Qz,.613*n.Kz*n.Kzt*.85*Math.Pow(250/3.6,2)/1000,"qz uses Kzt");
  /* the engineer confirms a flat site: Kzt = 1 even on the hill profile */
  h.UserFlat=true;var fl=WindAssessment.Calculate(h,10,250,.85)[0];Check(fl.Kzt==1&&fl.Shape.StartsWith("Flat"),"confirmed flat site gives Kzt 1");h.UserFlat=false;
  // Site in the lower half of the hill: Kzt = 1 with condition 3 not met.
  Func<int,double,double> below=(r,dist)=>r==1?(dist<500?Math.Min(60,10+dist*0.2):Math.Max(0,60-(dist-500)*60/600.0)):r==13?Math.Max(0,10-dist*10/200.0):0;var lower=Flat(30,below);var ln=WindAssessment.Calculate(lower,10,250,.85)[0];Check(ln.Kzt==1,"site below upper half is not amplified");Check(ln.TopographicChecks.Any(r=>r[0].StartsWith("Condition 3")&&r[1]=="NOT MET")&&ln.TopographicReason.Contains("upper half"),"lower-half reason explained");
  // STAAD wind input.
  var building=new WindBuildingInput{Width=12,Length=24,Eave=6,Apex=8,Kd=.85};var flat=WindAssessment.Calculate(Flat(30),building.Height,250,.85,building.Height);var profile=WindStaadInput.Profile(building,250,.85,flat);Check(profile.Any(r=>Math.Abs(r.Height-6)<1e-9)&&profile.Any(r=>Math.Abs(r.Height-8)<1e-9)&&profile.Any(r=>Math.Abs(r.Height-7)<1e-9),"profile includes eave, mean roof and apex");Check(profile.Select(r=>r.Direction).Distinct().Count()==8,"eight directions");var p0=profile.First(r=>r.Direction=="N"&&Math.Abs(r.Height-6)<1e-9);Near(p0.Qz,.613*WindBuildingLoads.Kz("C",6)*.85*Math.Pow(250/3.6,2)/1000,"qz value",1e-12);
  var bands=WindStaadInput.WallBands(building,250,flat);Check(bands.Select(x=>x.Type).Distinct().Count()==4,"four principal axes");Check(bands.All(x=>Math.Abs(x.Combined-(x.Windward+Math.Abs(x.Leeward)))<1e-12&&x.Windward>0&&x.Leeward<0),"windward plus leeward suction");var rows=WindBuildingLoads.Calculate(building,250,flat);var ww=rows.First(r=>r.Surface=="Windward wall"&&r.GCpi>0&&Math.Abs(r.Z-building.Eave)<1e-9&&r.Direction==bands[0].Axis);Near(bands.First(x=>x.Type==1&&Math.Abs(x.Top-building.Eave)<1e-9).Windward,ww.Q*ww.G*.8,"windward external pressure at band top");
  string cmd=WindStaadInput.Commands(bands);Check(cmd.StartsWith("UNIT METER KN\nDEFINE WIND LOAD")&&cmd.Contains("TYPE 4")&&cmd.Contains(" HEIG "),"STAAD command block");var line=cmd.Split('\n').First(x=>x.StartsWith("INT "));var parts=line.Split(new[]{" HEIG "},StringSplitOptions.None);Check(parts[0].Split(' ').Length-1==parts[1].Split(' ').Length,"INT and HEIG counts match");
  var report=WindReportFile.Create(14.6,121,"III-V",10,.85,Flat(30),false,new WindBuildingInput{Width=12,Length=24,Eave=6,Apex=8,Kd=.85},"Test project","Test location");var titles=report.Sections.Select(x=>x.Title).ToList();Check(titles.Contains("Exposure category determination by direction")&&titles.Contains("Topographic factor Kzt: criteria and substitution by direction")&&titles.Contains("STAAD wind input data"),"wind report has exposure, Kzt and STAAD sections: "+string.Join(" / ",titles));string html=System.Text.RegularExpressions.Regex.Replace(report.Html(),"data:image/[^'\"]+","");Check(html.Contains("DEFINE WIND LOAD")&&html.Contains("207A.8.1")&&!html.Contains("NaN"),"wind report content");
  // Terrain profile: one scale for X and Y times the stated vertical exaggeration.
  var sc=TerrainProfileScale.Create(-3200,3200,0,60,0,0,700,106,1);Near(sc.YScale,sc.XScale,"true scale when VE = 1");double ve=TerrainProfileScale.AutoExaggeration(-3200,3200,0,60,700,106);Check(ve==10,"auto VE picks 10x for 60 m relief over 6.4 km: "+ve);sc=TerrainProfileScale.Create(-3200,3200,0,60,0,0,700,106,ve);Near(sc.YScale/sc.XScale,ve,"Y scale = VE × X scale");Near(sc.X(3200)-sc.X(-3200),700,"profile spans full width",1e-9);Check(TerrainProfileScale.AutoExaggeration(-500,500,0,400,700,106)==1,"steep relief stays at true scale");
  // Apex dimension is measured vertically from ground directly below the apex, for every ridge orientation.
  for(int ridge=0;ridge<4;ridge++){var bi=new WindBuildingInput{Width=12,Length=24,Eave=6,Apex=8,RidgeDirection=ridge};var v=WindBuildingGeometry.Vertices(bi);var datum=WindBuildingGeometry.ApexDatum(bi);Near(datum.X,v[8].X,"apex datum below apex X "+ridge);Near(datum.Y,v[8].Y,"apex datum below apex Y "+ridge);Near(datum.Z,0,"apex datum at ground");Near(v[8].Z,8,"apex height");}
  // Traced source-map contours: georeferenced inside the Philippine map extent, with the published speed labels.
  foreach(var cat in new[]{"I","II","III-V"}){var lines=WindTin.Contours(cat);Check(lines.Count>500,"traced strokes for "+cat+": "+lines.Count);Check(lines.All(x=>x.Lat1>3&&x.Lat1<22&&x.Lon1>115&&x.Lon1<128),"contours inside the map extent for "+cat);Check(lines.All(x=>x.Speed>=240&&x.Speed<=340&&x.Speed%10==0),"contour speeds are 10 km/h steps");}
  int zoom=WindMapViewport.ZoomForRadius(14.6,3200,900,700);var edge=WindAssessment.Destination(14.6,121,90,3200);var px=WindMapViewport.Pixel(edge[0],edge[1],14.6,121,zoom,900,700);Check(px[0]<=900&&px[0]>450,"report map keeps the full terrain circle in frame at zoom "+zoom);var centre=WindMapViewport.Pixel(14.6,121,14.6,121,zoom,900,700);Near(centre[0],450,"site centred X");Near(centre[1],350,"site centred Y");
  Console.WriteLine("PASS: "+checks+" exposure ±45° sector, Kzt criteria/substitution and STAAD wind input checks");}
}
